/* Pixel board: near-black, vivid purple, no webfonts. */
:root {
  --paper: #07060c;
  --panel: #0f0b1a;
  --panel2: #140e24;
  --ink: #f5f2ff;
  --mut: #a79ec7;
  --faint: #2b2144;
  --accent: #a855f7;
  --accent2: #c084fc;
  --accent-deep: #7c3aed;
  --shadow: #2a1650;
  --green: #4ade80;
  --red: #f87171;
  --mono: ui-monospace, 'Cascadia Mono', 'SF Mono', Menlo, Consolas, 'Liberation Mono', monospace;
}
* { box-sizing: border-box; }
html { background: var(--paper); }
body {
  margin: 0 auto;
  max-width: 1180px;
  padding: 28px 10px 40px;
  background: var(--paper);
  color: var(--ink);
  font-family: var(--mono);
  font-size: 14px;
  line-height: 1.55;
}
h1, h2, h3 { line-height: 1.2; text-transform: uppercase; letter-spacing: 0.04em; }
a { color: var(--accent2); }
::selection { background: var(--accent); color: #fff; }

/* Masthead. */
.masthead {
  display: grid;
  grid-template-columns: 1fr 120px;
  gap: 8px 20px;
  border-bottom: 3px solid var(--accent-deep);
  padding-bottom: 18px;
}
.mast-text { grid-column: 1; }
.kicker {
  margin: 0 0 10px;
  font-size: 11px;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: var(--mut);
}
h1 {
  margin: 0 0 12px;
  font-size: 48px;
  font-weight: 800;
  letter-spacing: 0.02em;
  color: var(--ink);
  text-shadow: 4px 4px 0 #4c1d95;
}
h1 .hl { color: var(--accent); }
.sub { margin: 0; max-width: 62ch; font-size: 15px; color: var(--ink); }
.mascot { grid-column: 2; grid-row: 1 / 3; text-align: center; align-self: start; }
.mascot svg {
  width: 104px;
  height: 104px;
  image-rendering: pixelated;
  filter: drop-shadow(0 0 12px rgba(168, 85, 247, 0.45));
}
.mascot-name {
  margin: 4px 0 0;
  font-size: 10px;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--mut);
}
.flower-field {
  grid-column: 1 / -1;
  margin-top: 14px;
  border: 2px solid var(--accent-deep);
  background: #0a0714;
  box-shadow: 4px 4px 0 var(--shadow);
}
.flower-field svg { display: block; width: 100%; height: 56px; }
.ledger-line {
  grid-column: 1 / -1;
  display: grid;
  grid-template-columns: repeat(6, 1fr);
  margin: 18px 0 0;
  border: 2px solid var(--accent-deep);
  background: var(--panel);
  box-shadow: 4px 4px 0 var(--shadow);
}
.ledger-line div { padding: 10px 12px; border-right: 2px solid var(--faint); }
.ledger-line div:last-child { border-right: 0; }
.ledger-line dt {
  font-size: 10px;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--mut);
}
.ledger-line dd { margin: 2px 0 0; font-size: 19px; font-weight: 700; color: var(--ink); }
.proof-line {
  grid-column: 1 / -1;
  margin: 16px 0 0;
  font-size: 12px;
  color: var(--mut);
}
.proof-line b { color: var(--accent2); }

.tabs { display: flex; gap: 8px; margin: 18px 0; }
.tab {
  font-family: var(--mono);
  font-size: 12px;
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  padding: 9px 16px;
  background: var(--panel);
  color: var(--ink);
  border: 2px solid var(--accent-deep);
  box-shadow: 3px 3px 0 var(--shadow);
  cursor: pointer;
}
.tab:hover { background: var(--panel2); }
.tab.active { background: var(--accent); border-color: var(--accent); color: #fff; box-shadow: 3px 3px 0 #4c1d95; }

.toolbar {
  display: flex;
  flex-wrap: wrap;
  align-items: end;
  gap: 12px;
  margin-bottom: 10px;
}
.toolbar label {
  font-size: 11px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--mut);
}
.toolbar input, .toolbar select {
  font-family: var(--mono);
  font-size: 13px;
  color: var(--ink);
  background: var(--panel);
  border: 2px solid var(--accent-deep);
  padding: 7px 9px;
  margin-left: 6px;
}
.toolbar input:focus, .toolbar select:focus { outline: 2px solid var(--accent); outline-offset: 0; }
.toolbar input { width: 230px; }
.chips { display: flex; gap: 6px; }
.chip {
  font-family: var(--mono);
  font-size: 12px;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  padding: 7px 12px;
  background: var(--panel);
  color: var(--ink);
  border: 2px solid var(--accent-deep);
  cursor: pointer;
}
.chip.active { background: var(--accent); border-color: var(--accent); color: #fff; }
.count { margin: 0 0 10px; font-size: 12px; color: var(--mut); }

.table-wrap {
  border: 2px solid var(--accent-deep);
  background: var(--panel);
  box-shadow: 4px 4px 0 var(--shadow);
  overflow-x: auto;
}
table { width: 100%; border-collapse: collapse; font-size: 12px; }
thead th {
  text-align: left;
  font-size: 10px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: #fff;
  background: var(--accent-deep);
  padding: 9px 5px;
  white-space: nowrap;
}
tbody td { padding: 8px 5px; border-bottom: 1px solid var(--faint); vertical-align: top; }
tbody tr:nth-child(even) { background: #100c1e; }
tbody tr:hover { background: #1c1332; }
.num { text-align: right; font-variant-numeric: tabular-nums; }
.pname { font-weight: 700; display: block; }
td small, .lede small { color: var(--mut); font-size: 11px; }
.cat { color: var(--mut); }
.up { color: var(--green); font-weight: 700; }
.down { color: var(--red); font-weight: 700; }
.verdict {
  display: inline-block;
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.1em;
  padding: 3px 8px;
  border: 2px solid var(--ink);
}
.verdict.FARM { background: var(--accent); border-color: var(--accent); color: #fff; }
.verdict.THIN { background: transparent; color: var(--accent2); border-color: var(--accent2); }
.verdict.SKIP { background: transparent; color: var(--mut); border-style: dashed; border-color: var(--mut); }
.footnote, .caption { font-size: 12px; color: var(--mut); }
.lede { font-size: 14px; max-width: 72ch; }
.spark { vertical-align: middle; display: block; }

.method-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 18px; }
.panel {
  background: var(--panel);
  border: 2px solid var(--accent-deep);
  box-shadow: 4px 4px 0 var(--shadow);
  padding: 18px 20px;
}
.panel h3 { margin: 0 0 10px; font-size: 13px; color: var(--accent2); }
.panel h3:not(:first-child) { margin-top: 22px; }
.panel p { margin: 0 0 10px; }
.formula {
  font-size: 15px;
  font-weight: 700;
  color: var(--accent2);
  background: #0a0714;
  border: 2px solid var(--accent);
  padding: 12px;
}
table.proof { font-size: 12px; }
table.proof thead th { padding: 7px 8px; }
table.proof td { padding: 7px 8px; border-bottom: 1px solid var(--faint); }
#chart svg { width: 100%; height: auto; display: block; background: var(--panel); }

/* Detail dialog. */
dialog {
  border: 3px solid #fff;
  background: #050505;
  color: var(--ink);
  box-shadow: 8px 8px 0 var(--accent-deep);
  padding: 0;
  max-width: 640px;
  width: calc(100% - 40px);
  max-height: 92vh;
}
dialog::backdrop { background: rgba(7, 6, 12, 0.8); }
dialog .close {
  position: absolute;
  top: 10px;
  right: 10px;
  width: 32px;
  height: 32px;
  font-family: var(--mono);
  font-size: 18px;
  font-weight: 700;
  line-height: 1;
  background: var(--panel);
  color: var(--ink);
  border: 2px solid #fff;
  cursor: pointer;
}
dialog .close:hover { background: var(--accent); border-color: var(--accent); color: #fff; }
#detailBody, #calloutBody { padding: 22px 24px; max-height: calc(92vh - 4px); overflow-y: auto; }
#detailBody::after {
  content: "\25BC";
  display: block;
  text-align: center;
  color: var(--accent2);
  margin-top: 16px;
  font-size: 12px;
}
#detailBody h2, #calloutBody h2 { margin: 0 0 8px; font-size: 22px; }
#detailBody h2::before { content: "\2665  *  "; color: #ef4444; }
#detailBody h2 small, #calloutBody h2 small {
  display: block;
  font-size: 10px;
  letter-spacing: 0.16em;
  color: var(--mut);
  margin-bottom: 6px;
}
#detailBody h3, #calloutBody h3 { font-size: 13px; margin: 18px 0 8px; color: var(--accent2); }
.kv {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 0;
  margin: 14px 0;
  border-top: 2px solid var(--accent-deep);
}
.kv div { padding: 8px 0; border-bottom: 1px solid var(--faint); }
.kv dt { font-size: 10px; letter-spacing: 0.12em; text-transform: uppercase; color: var(--mut); }
.kv dd { margin: 2px 0 0; font-weight: 700; }
.steps { list-style: none; counter-reset: step; margin: 0; padding: 0; }
.steps li {
  counter-increment: step;
  position: relative;
  padding: 0 0 12px 44px;
}
.steps li::before {
  content: counter(step, decimal-leading-zero);
  position: absolute;
  left: 0;
  top: 0;
  width: 30px;
  height: 30px;
  line-height: 30px;
  text-align: center;
  font-size: 12px;
  font-weight: 700;
  color: #fff;
  background: var(--accent);
}
.steps .meta { font-size: 12px; color: var(--accent2); margin-top: 3px; }

footer { margin-top: 26px; border-top: 2px solid var(--accent-deep); padding-top: 12px; }
footer p { font-size: 11px; color: var(--mut); margin: 0; }
.view[hidden] { display: none; }

.callout-btn{display:inline-flex;align-items:center;gap:8px;margin-top:14px;font-family:var(--mono);font-size:12px;font-weight:700;text-transform:uppercase;padding:9px 16px;background:var(--panel);color:var(--ink);border:2px solid var(--accent-deep);box-shadow:3px 3px 0 var(--shadow);cursor:pointer}
.callout-btn svg{width:16px;height:16px;color:#a855f7;image-rendering:pixelated}
.co-note,.co-hint,.co-imgfail,.co-imghint,.co-empty{font-size:12px;color:var(--mut)}
.co-label{display:block;font-size:11px;text-transform:uppercase;color:var(--mut);margin:12px 0 0}
.co-label textarea,.co-label input,.co-row input{width:100%;font-family:var(--mono);font-size:13px;color:var(--ink);background:var(--panel);border:2px solid var(--accent-deep);padding:7px 9px;margin-top:6px}
.co-row{display:flex;gap:8px;margin-top:10px;align-items:center}
.co-btn{font-family:var(--mono);font-size:12px;font-weight:700;text-transform:uppercase;padding:7px 12px;background:var(--panel);color:var(--ink);border:2px solid var(--accent-deep);cursor:pointer}
.co-btn:disabled{opacity:.45;cursor:default}
.co-post{background:var(--accent);border-color:var(--accent);color:#fff;margin-top:12px}
#coPrev img{max-width:100%;max-height:180px;display:block;margin-top:8px;border:2px solid var(--accent-deep)}
.co-gifres{display:flex;flex-wrap:wrap;gap:8px;margin-top:10px}
.co-gifres img{width:120px;height:68px;object-fit:cover;border:2px solid var(--accent-deep);cursor:pointer}
.co-msg{font-size:12px;color:var(--accent2)}
.co-card{border:2px solid var(--accent-deep);background:var(--panel);padding:12px;margin:0 0 10px}
.co-card p{margin:0 0 8px;overflow-wrap:anywhere}
.co-card img{max-width:100%;max-height:220px;display:block;margin:0 0 8px;border:2px solid var(--accent-deep)}
.co-card audio{width:100%;margin:0 0 8px}
.co-badge{display:inline-block;font-size:10px;font-weight:700;letter-spacing:.12em;text-transform:uppercase;background:var(--accent);color:#fff;padding:3px 8px;margin-bottom:8px}
.co-del{font-family:var(--mono);font-size:11px;font-weight:700;padding:5px 10px;background:transparent;color:var(--mut);border:2px dashed var(--mut);cursor:pointer}
```

