  /* Callouts: local-only notes. */
  const CO_KEY = 'radar-callouts-v1', CO_GK = 'radar-giphy-key', CO_BETA = 'dc6zaTOxFJmzC';
  let coList = null, coAttach = null, coVoice = null, coRec = null;
